from itertools import accumulate


class Solution:
    def waysToSplit(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        n = len(nums)
        pre = list(accumulate(nums))
        total = pre[-1]
        ans = 0
        for i in range(n - 2):
            if 2 * pre[i] > total:
                break
            for j in range(i + 1, n - 1):
                mid = pre[j] - pre[i]
                if mid < pre[i]:
                    continue
                if mid > total - pre[j]:
                    break
                ans += 1
        return ans % MOD

