class Solution {
public:
    int waysToSplit(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<long> pre(n);
        partial_sum(nums.begin(), nums.end(), pre.begin());
        long total = pre[n - 1], ans = 0;
        for (int i = 0; i < n - 2 && 2 * pre[i] <= total; ++i)
            for (int j = i + 1; j < n - 1; ++j) {
                long mid = pre[j] - pre[i], right = total - pre[j];
                if (mid < pre[i]) continue;
                if (mid > right) break;
                ++ans;
            }
        return (int)(ans % MOD);
    }
};

