class Solution {
    private int lowerBound(long[] a, long v, int from, int to) {
        int lo = from, hi = to;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < v) lo = mid + 1; else hi = mid; }
        return lo;
    }
    private int upperBound(long[] a, long v, int from, int to) {
        int lo = from, hi = to;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= v) lo = mid + 1; else hi = mid; }
        return lo;
    }
    public int waysToSplit(int[] nums) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        long[] pre = new long[n];
        for (int i = 0; i < n; i++) pre[i] = (i == 0 ? 0 : pre[i - 1]) + nums[i];
        long total = pre[n - 1], ans = 0;
        for (int i = 0; i < n - 2 && 2 * pre[i] <= total; i++) {
            int lo = lowerBound(pre, 2 * pre[i], i + 1, n - 1);
            int hi = upperBound(pre, (total + pre[i]) / 2, i + 1, n - 1);
            if (hi > lo) ans += hi - lo;
        }
        return (int) (ans % MOD);
    }
}

